const commandsButton=document.createElement('button');commandsButton.id='toggle-commands';commandsButton.className='hud-extra';commandsButton.innerHTML=ico('people');commandsButton.title='Settlement orders (O)';commandsButton.setAttribute('aria-label','Toggle command panel');commandsButton.setAttribute('aria-controls','g-inspector');$('.g-header').append(commandsButton);
const fullscreenButton=document.createElement('button');fullscreenButton.id='fullscreen-game';fullscreenButton.className='hud-extra';fullscreenButton.innerHTML=ico('focus');fullscreenButton.title='Fullscreen (F)';fullscreenButton.setAttribute('aria-label','Enter fullscreen');$('.g-header').append(fullscreenButton);
fullscreenButton.onclick=()=>{if(document.fullscreenElement)document.exitFullscreen().catch(()=>notify('Could not leave fullscreen.'));else document.documentElement.requestFullscreen().catch(()=>notify('Fullscreen is unavailable in this browser.'));};
if(!document.fullscreenEnabled){fullscreenButton.disabled=true;fullscreenButton.title='Fullscreen is unavailable in this browser';}
