// Keep controls mounted while live statistics change, so clicks and focus are stable.
function patchChildren(parent:Node,next:Node){
  const fresh=[...next.childNodes];
  for(let i=0;i<fresh.length;i++){
    const n=fresh[i],old=parent.childNodes[i];
    if(!old){parent.appendChild(n.cloneNode(true));continue;}
    if(old.nodeType!==n.nodeType||(old instanceof Element&&n instanceof Element&&old.tagName!==n.tagName)){parent.replaceChild(n.cloneNode(true),old);continue;}
    if(old.nodeType===Node.TEXT_NODE){if(old.textContent!==n.textContent)old.textContent=n.textContent;continue;}
    if(old instanceof Element&&n instanceof Element){
      if(old===document.activeElement&&['INPUT','SELECT'].includes(old.tagName))continue;
      for(const a of [...old.attributes])if(!n.hasAttribute(a.name))old.removeAttribute(a.name);
      for(const a of [...n.attributes])if(old.getAttribute(a.name)!==a.value)old.setAttribute(a.name,a.value);
      patchChildren(old,n);
    }
  }
  while(parent.childNodes.length>fresh.length)parent.removeChild(parent.lastChild!);
}
let panelKey='';
function updatePanel(){
  const focused=document.activeElement as HTMLElement|null;const focusKey=focused?.getAttribute('data-job')?{job:focused.dataset.job,delta:focused.dataset.delta}:null;
  const focusedId=focused&&$('#g-inspector').contains(focused)?focused.id:'';
  const html=activeTab==='army'?armyPanel():activeTab==='chronicle'?chroniclePanel():activeTab==='realm'?realmPanel():view.selectedWorker>=0?workerPanel():view.selectedBuilding>=0?buildingPanel():selectedNode>=0?nodePanel():overview();
  const nextKey=[activeTab,view.selectedCity,view.selectedWorker,view.selectedBuilding,selectedNode].join(':');
  if(panelKey!==nextKey){$('#g-inspector').innerHTML=html;$('#g-inspector').scrollTop=0;panelKey=nextKey;}else{const template=document.createElement('template');template.innerHTML=html;patchChildren($('#g-inspector'),template.content);}
  const bind=(selector:string,fn:()=>void)=>{const b=document.querySelector<HTMLElement>(selector);if(b)b.onclick=fn;};
  bind('#back-village',()=>{view.selectedBuilding=-1;view.selectedWorker=-1;selectedNode=-1;updatePanel();});bind('#back-neighbors',()=>{view.selectedCity=0;updatePanel();});
  bind('#recruit-worker',()=>perform({type:'recruit',kind:'worker'},'A villager is joining your settlement.'));bind('#train-spear',()=>perform({type:'recruit',kind:'spear'},'Spearman added to the training queue.'));
  bind('#inspect-hall',()=>{view.selectedBuilding=buildingsOf(game,0,'hall')[0].id;view.selectedWorker=-1;selectedNode=-1;updatePanel();});
  bind('#upgrade-selected',()=>perform({type:'upgrade',id:view.selectedBuilding},'Upgrade ordered. Your builders will get to work.'));
  bind('#open-atlas',goAtlas);bind('#visit-rival',()=>visitCity(view.selectedCity));bind('#send-gift',()=>perform({type:'gift',target:view.selectedCity},'Your gift improved relations.'));
  bind('#send-raid',()=>perform({type:'raid',target:view.selectedCity,count:Number($<HTMLInputElement>('#raid-count').value)},'Your spearmen are on the march.'));
  bind('#harvest-here',()=>{const p=coords(selectedNode),w=workersOf(game,0).filter(w=>!w.cargo).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(!w){notify('Every worker is carrying a load. Try again after a delivery.');return;}perform({type:'harvest',id:w.id,node:selectedNode},`${w.name} is on the way.`,()=>{view.selectedWorker=w.id;selectedNode=-1;});});
  const select=document.querySelector<HTMLSelectElement>('#worker-job');if(select)select.onchange=()=>{perform({type:'assign',id:view.selectedWorker,job:select.value},'New job assigned.');select.blur();};
  document.querySelectorAll<HTMLButtonElement>('[data-job]').forEach(b=>b.onclick=()=>{const job=b.dataset.job as Job,n=workersOf(game,0).filter(w=>w.job===job).length;perform({type:'job',job,count:n+Number(b.dataset.delta)},'Workforce updated.');});
  document.querySelectorAll<HTMLButtonElement>('[data-city]').forEach(b=>b.onclick=()=>{view.selectedCity=Number(b.dataset.city);view.selectedBuilding=-1;view.selectedWorker=-1;selectedNode=-1;updatePanel();});
  document.querySelectorAll<HTMLButtonElement>('[data-building]').forEach(b=>b.onclick=()=>{view.selectedBuilding=Number(b.dataset.building);updatePanel();});
  document.querySelectorAll<HTMLButtonElement>('[data-train]').forEach(b=>b.onclick=()=>perform({type:'recruit',kind:b.dataset.train},'Added to your training queue.'));
  document.querySelectorAll<HTMLButtonElement>('[data-deploy]').forEach(b=>b.onclick=async()=>{armyMode=true;const kind=b.dataset.deploy as UnitKind;await perform({type:'deploy',kind,count:Math.min(5,reserve(game.cities[0],kind))},'Troops deployed. Drag to select; right-click to command.',()=>{view.selectedUnits=(game.soldiers||[]).filter(u=>u.city===0&&u.kind===kind).map(u=>u.id);});updateArmyMode();});
  document.querySelectorAll<HTMLButtonElement>('[data-research]').forEach(b=>b.onclick=()=>perform({type:'research',kind:b.dataset.research},'Research started.'));
  bind('#army-select-all',()=>{view.selectedUnits=(game.soldiers||[]).filter(u=>u.city===0).map(u=>u.id);armyMode=true;updateArmyMode();updatePanel();});
  bind('#army-mode',()=>{armyMode=!armyMode;updateArmyMode();updatePanel();});
  bind('#army-hold',()=>perform({type:'units',ids:view.selectedUnits||[],order:'hold'},'Soldiers hold their ground.'));
  bind('#army-return',()=>perform({type:'units',ids:view.selectedUnits||[],order:'return'},'Soldiers return to the garrison.'));
  if(focusKey)document.querySelector<HTMLElement>(`[data-job="${focusKey.job}"][data-delta="${focusKey.delta}"]`)?.focus({preventScroll:true});
  else if(focusedId)document.getElementById(focusedId)?.focus({preventScroll:true});
  drawPortrait();
}
function chooseBuild(kind:BuildingKind|null){view.placing=kind;$('#build-hint').hidden=!kind;document.querySelectorAll('[data-build]').forEach(b=>b.classList.toggle('active',b.getAttribute('data-build')===kind));if(kind){mapMode=false;setMapTabs();$('#build-hint').innerHTML=`<strong>${CATALOG[kind].name}</strong>${costs(CATALOG[kind].cost)}<span>Click clear ground · Esc to cancel</span>`;view.hover={x:Math.floor(view.camera.x)+4,y:Math.floor(view.camera.y)+4};canvas.focus();}canvas.style.cursor=kind?'crosshair':'grab';}
