mini.onclick=e=>{const r=mini.getBoundingClientRect();view.camera.x=(e.clientX-r.left)/r.width*MAP_SIZE;view.camera.y=(e.clientY-r.top)/r.height*MAP_SIZE;if(view.camera.zoom<12)view.camera.zoom=24;mapMode=false;setMapTabs();};
canvas.onkeydown=e=>{if(e.key==='Home'){e.preventDefault();goHome();}if(e.key.startsWith('Arrow')){e.preventDefault();const dx=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0,dy=e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0;if(view.placing){view.hover??={x:game.cities[0].x+5,y:game.cities[0].y+5};view.hover.x+=dx;view.hover.y+=dy;}else{view.camera.x+=dx*3;view.camera.y+=dy*3;}}if(e.key==='Enter'&&view.placing&&view.hover){e.preventDefault();usePoint(view.hover.x,view.hover.y);}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement).tagName)||$<HTMLDialogElement>('#g-dialog').open)return;if(e.code==='Space'&&(e.target as HTMLElement).tagName!=='BUTTON'){e.preventDefault();if(!online)paused=!paused;updateStats();}if(e.key==='Escape')chooseBuild(null);if(/^[1-8]$/.test(e.key)){e.preventDefault();const kinds:BuildingKind[]=['house','farm','lumber','quarry','mine','store','barracks','watchtower'];if(mapMode)goHome();chooseBuild(kinds[Number(e.key)-1]);}});
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)');
function draw(now:number){if(!paused&&!reducedMotion.matches)view.now=now;view.camera.offsetX=commandsOpen&&window.innerWidth>=900?-(window.innerWidth>=1500?165:150):0;view.camera.offsetY=-8;const r=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);if(canvas.width!==Math.round(r.width*dpr)||canvas.height!==Math.round(r.height*dpr)){canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);renderRealm(ctx,game,r.width,r.height,view,miniBase);drawMinimap(miniCtx,game,miniBase,view,256,256,r.width,r.height);}
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes((e.target as HTMLElement).tagName)||$<HTMLDialogElement>('#g-dialog').open)return;if(e.key.toLowerCase()==='o')setCommands(!commandsOpen);if(e.key.toLowerCase()==='m')goAtlas();if(e.key.toLowerCase()==='f')fullscreenButton.click();if(e.key==='Escape'&&!view.placing&&window.innerWidth<900)setCommands(false);});
const dialog=$<HTMLDialogElement>('#g-dialog');let wasPaused=false;
function showDialog(html:string){wasPaused=paused;paused=true;dialog.innerHTML=`<button class="g-dialog-close" aria-label="Close dialog">${ico('close')}</button>${html}`;dialog.showModal();$('.g-dialog-close').onclick=()=>dialog.close();updateStats();}
dialog.onclose=()=>{paused=wasPaused;updateStats();};
function help(){showDialog(`<div class="g-eyebrow">YOUR FIRST DAYS IN WILLOWMERE</div><h2 id="g-dialog-title">A village that follows your lead.</h2><p class="dialog-lead">A real-time settlement game, with real little people doing the work.</p><div class="guide-step">${ico('tree')}<p><strong>Give everyone a job.</strong>Use + and − in the Village panel. Woodcutters walk to trees, gather a load, and return it to a hall, storehouse, or lumber camp. Resources are credited on delivery.</p></div><div class="guide-step">${ico('builder')}<p><strong>Build something worth coming home to.</strong>Pick a building below the map, then click clear ground within your village boundary. Builders walk to the site. Cottages add housing; camps speed up gathering.</p></div><div class="guide-step">${ico('people')}<p><strong>Make it your own.</strong>Recruit villagers, inspect and upgrade buildings, and train spearmen. Click a worker to change their job. Right-click a nearby resource to give that worker a direct gathering order.</p></div><div class="guide-step">${ico('world')}<p><strong>You have neighbors.</strong>Explore a 256 × 256 seeded realm. AI governors run real cities with working villagers. Visit, send gifts, or march a raiding party out to take resources.</p></div><p class="dialog-footnote">Drag to pan · scroll or +/− to zoom · Home returns to your village · Space pauses · 1–8 select buildings · arrow keys position a blueprint, Enter places it · Escape cancels.<br>Army: train and deploy soldiers in the Army panel, then drag-select and right-click to move or attack. Play with friends: join the same host and seed with your own name. Multiplayer uses 1× speed. Classic mode preserves the original simulator and its exports.</p>`);}
$('#how-to').onclick=help;$('#help-footer').onclick=help;
function download(blob:Blob,name:string){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
$('#save-menu').onclick=()=>{if(online){lobby();return;}persist();showDialog(`<div class="g-eyebrow">SAVE & LOAD</div><h2 id="g-dialog-title">Realm menu</h2><p class="dialog-lead">Your settlement is saved on this device. Keep a world file to carry it elsewhere.</p><div class="realm-save-card">${ico('world')}<div><strong>${esc(game.seed)}</strong><small>${game.cities.length} settlements · ${MAP_SIZE*MAP_SIZE} tiles · Day ${Math.floor(game.time/60)+1}</small></div></div><button class="g-button green full" id="download-realm">${ico('save')}Download world file</button><label class="g-import-label">Open a settlement world file<input id="load-realm" type="file" accept=".json,application/json"></label><p role="alert" id="load-error" class="g-error"></p><hr class="side-rule"><h3 class="new-realm-title">A fresh beginning</h3><form id="new-realm-form"><label class="g-form-label">World seed<input id="new-seed" maxlength="48" required value="${esc(game.seed)}" autocomplete="off"></label><label class="g-form-label">AI-controlled rivals<select id="rival-count">${[8,16,24,35].map(n=>`<option value="${n}" ${n===game.cities.length-1?'selected':''}>${n} rival cities</option>`).join('')}</select></label><p class="dialog-footnote">Starting a new realm replaces this device’s current settlement. Download it first to keep it. Your Classic mode save is separate.</p><button class="g-button soft full" type="submit">${ico('plus')}Found a new village</button></form>`);$('#download-realm').onclick=()=>download(new Blob([saveRealm(game)],{type:'application/json'}),`tiny-civ-realm-${game.seed.replace(/[^a-z0-9-]/gi,'-')}.json`);
  $('#new-realm-form').onsubmit=e=>{e.preventDefault();game=createRealm($<HTMLInputElement>('#new-seed').value,Number($<HTMLSelectElement>('#rival-count').value));miniBase=minimapCanvas(game);wasPaused=false;dialog.close();chooseBuild(null);goHome();persist();notify('A new realm. Your first orders await.');};
  $('#load-realm').onchange=async()=>{const f=$<HTMLInputElement>('#load-realm').files?.[0];if(!f)return;try{if(f.size>3000000)throw Error('Choose a file smaller than 3 MB.');const restored=loadRealm(await f.text());game=restored;miniBase=minimapCanvas(game);wasPaused=false;dialog.close();chooseBuild(null);goHome();persist();notify('Your settlement is restored.');}catch(e){$('#load-error').textContent=e instanceof Error?e.message:'Could not read this world.';}};
};
let last=performance.now(),acc=0,lastPanel=0,lastSave=0,lastMini=0;
function frame(now:number){const dt=Math.min((now-last)/1000,.2);last=now;if(!online&&!paused&&!document.hidden&&!dialog.open){acc+=dt*speed;while(acc>=.1){tick(game,.1);acc-=.1;}}draw(now);if(now-lastPanel>700){updateStats();updatePanel();lastPanel=now;}if(now-lastSave>10000){persist();lastSave=now;}if(now-lastMini>15000){miniBase=minimapCanvas(game);lastMini=now;}requestAnimationFrame(frame);}
function rememberedName(){try{return localStorage.getItem('tiny-civ-player-name')||'';}catch{return '';}}
function leaveShared(){network.leave();online=false;game=solo||createRealm('wildflower');solo=null;miniBase=minimapCanvas(game);wasPaused=false;dialog.close();goHome();updateStats();$('#network-status').textContent='Solo · AI rivals';}
function inviteURL(){const u=new URL(location.href);u.search='';u.searchParams.set('room',network.seed);u.searchParams.set('server',network.endpoint);return u.toString();}
function lobby(){if(online&&network.status==='online'){
  showDialog(`<div class="g-eyebrow">SHARED REALM · PC HOSTED</div><h2 id="g-dialog-title">The war room</h2><p class="dialog-lead">Seed <b>${esc(network.seed)}</b> · ${network.roster.length}/5 villages claimed</p><div class="room-roster">${network.roster.map(p=>`<button class="roster-player" data-visit="${p.city}"><i class="${p.online?'online':''}"></i><span>${esc(p.name)}<small>${esc(game.cities[p.city].name)} · ${p.city===0?'You':p.online?'Connected':'Away'}</small></span>↗</button>`).join('')}</div><label class="g-form-label">Invite friends (seed + server)<input id="invite-url" readonly value="${esc(inviteURL())}"></label><button id="copy-invite" class="g-button green full">Copy invitation</button><p class="dialog-footnote">Keep the host PC and tunnel running. The host saves this world; it pauses when everyone disconnects. New villages have 2 minutes of protection.</p><button id="leave-world" class="g-button soft full">Leave shared world · return to solo</button>`);
  $('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(inviteURL());notify('Invitation copied. Friends enter their own player name.');}catch{$<HTMLInputElement>('#invite-url').select();notify('Select and copy the invitation above.');}};
  document.querySelectorAll<HTMLButtonElement>('[data-visit]').forEach(b=>b.onclick=()=>{visitCity(Number(b.dataset.visit));dialog.close();});
  $('#leave-world').onclick=leaveShared;return;}
  showDialog(`<div class="g-eyebrow">UP TO FIVE FRIENDS · ONE LIVING WORLD</div><h2 id="g-dialog-title">Found your village together.</h2><p class="dialog-lead">Enter a name and the same seed as your friends. Each player rules a village in the shared realm.</p><form id="join-form"><label class="g-form-label">Player name<input id="player-name" required minlength="2" maxlength="20" autocomplete="nickname" value="${esc(network.name||rememberedName()||'')}"></label><label class="g-form-label">Room seed<input id="room-seed" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+" value="${esc(params.get('room')||network.seed||'friends-'+Math.random().toString(36).slice(2,7))}"></label><label class="g-form-label">Host server<input id="host-server" required type="text" placeholder="wss://your-tunnel.trycloudflare.com" value="${esc(params.get('server')||defaultServer||network.endpoint)}"></label><p role="alert" class="g-error" id="join-error"></p><button id="join-world" type="submit" class="g-button green full">Join shared world</button></form>${online?'<button id="cancel-online" class="g-button soft full">Return to solo</button>':''}<p class="dialog-footnote">Your browser remembers your name’s reconnect key. Use the same browser to return. This is a friends-only guest login, with five permanent player slots per seed. Keep your solo save by downloading it in Menu.</p>`);
  if(online)$('#cancel-online').onclick=leaveShared;
  $('#join-form').onsubmit=e=>{e.preventDefault();try{const name=playerName($<HTMLInputElement>('#player-name').value),seed=roomSeed($<HTMLInputElement>('#room-seed').value);if(!name)throw Error('Use 2–20 letters, numbers, spaces, underscores, or hyphens.');if(!seed)throw Error('Use a seed with 3–32 letters, numbers, underscores, or hyphens.');const endpoint=serverURL($<HTMLInputElement>('#host-server').value);if(!online){persist();solo=game;}online=true;try{localStorage.setItem('tiny-civ-player-name',name);}catch{}network.join(endpoint,seed,name);wasPaused=false;dialog.close();notify('Connecting to the shared world…');}catch(error){$('#join-error').textContent=error instanceof Error?error.message:'Could not join.';}};
}
$('#multiplayer-menu').onclick=lobby;
fetch(new URL('multiplayer.json',document.baseURI)).then(r=>r.ok?r.json():null).then(c=>{if(c&&typeof c.server==='string'){try{defaultServer=serverURL(c.server);}catch{}}}).catch(()=>{}).finally(()=>{if(params.has('room'))lobby();});
window.addEventListener('pagehide',persist);updateStats();updatePanel();requestAnimationFrame(frame);if(saveError)notify(saveError);
